/** API05 独立 Collector。 */
public class CiqFaultyTrafficLightsCollector implements DataCollector {private static final Logger log=LoggerFactory.getLogger(CiqFaultyTrafficLightsCollector.class);private final CiqPagedJsonCollectorSupport<FaultyTrafficLightRecord> support;public CiqFaultyTrafficLightsCollector(LtaFaultyTrafficLightsClient client,CiqProperties p,CiqJsonStorageService storage,FaultyTrafficLightsParser parser,FaultyTrafficLightsValidator validator,FaultyTrafficLightsPersistenceService persistence,CiqAuditPersistenceService audit){support=new CiqPagedJsonCollectorSupport<>("API05",CiqApiCode.API05,CollectorCode.CIQ_FAULTY_TRAFFIC_LIGHTS,client,p,p.getCollectors().getFaultyTrafficLights(),storage,parser::parse,validator::isValid,persistence==null?null:persistence::persist,audit,log);}public ModuleCode moduleCode(){return ModuleCode.CIQ;}public CollectorCode collectorCode(){return CollectorCode.CIQ_FAULTY_TRAFFIC_LIGHTS;}public CollectionResult collect(CollectionContext c){return support.collect(c);}}
